head.script:
scwin.contnId;
// var objTpCd;
scwin.vCurDate;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        tbox_user.hide();
        scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
        getContnId = $c.frame.path("../").fn_getContnId;
        scwin.contnId = getContnId();
        if (scwin.contnId !== "input") {
            getSysCode = $c.frame.path("../").fn_getSysCode;
            // objTpCd = getSysCode();
            // showObj(panel_mkt_gubun,false);

            await scwin.singleRead();

            // if(objTpCd == "1" || objTpCd == "6"){
            rdo_mkt_gubun.setValue(dts_NoticeContentSingle.getCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD"));
            // }

        } else {

            // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            await scwin.setIrInfoHeader();
            btn_delete.hide();
            const today = $c.ut.cGetToday2();
            const nextMonDay = $c.ut.calcMonth(today, 1);
            tbox_user.setValue(js_dep_nm);
            dts_noticeInfo.setCellData(dts_noticeInfo.getRowPosition(), "WRTR_EMP_NO", js_emp_no);
            if (js_market === "9") {
                rdo_mkt_gubun.setValue("9");
            } else {
                rdo_mkt_gubun.setValue(js_market);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30353.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30353.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        if (scwin.contnId === "input") {
            await scwin.save();
        } else {
            await scwin.update();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30353.btn_save_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "투자유의안내등록"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30353.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "투자유의안내등록"));
        await $c.win.alert(trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30353.trs_Save_OnFail" });
    }
};

