/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (dts_fileList.getRowCount() === 5) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30353.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30353.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30353.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30353.btn_cancel_onclick" });
    }
};

/**
 * @method
 * @name grd_userlist_OnClick
 * @description grd_userlist 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_userlist_OnClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30353.grd_userlist_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name singleRead
 * @description 투자유의안내 개별조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.singleRead = async function() {
    // 투자유의안내 개별조회

    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/IRMgt.do",
        ref : "dts_NoticeContentSingle,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name update
 * @description 투자유의안내 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    // 투자유의안내 수정

    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_content.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    let rtn = confirm('위사항을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_NoticeContentSingle.setCellData(dts_NoticeContentSingle.getRowPosition(), "LD_MKT_TP_CD", rdo_mkt_gubun.getValue());
        trs_Update.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/IRMgt.do",
            ref : "dts_NoticeContentSingle,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name save
 * @description 투자유의안내 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 투자유의안내 등록

    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_content.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_content.focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_content, 2000, "내용")) {
        tarea_content.text = "";
        tarea_content.focus();
        return false;
    }
    let rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/IRMgt.do",
            ref : "dts_noticeInfo,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description 투자유의안내 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    // 투자유의안내 삭제

    let rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_NoticeDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_NoticeDelete.insertRow();
        dts_NoticeDelete.setCellData(1, "CONTN_ID", scwin.contnId);
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/IRMgt.do",
            ref : "dts_NoticeDelete",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name setIrInfoHeader
 * @description CUD용 Header
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setIrInfoHeader = async function() {
    // CUD용 Header
    const sbmOptions = {
        id : "sbm_dts_noticeInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_noticeInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_noticeInfo.insertRow();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?file_id=" + scwin.contnId + "&attach_seq=" + attach_seq + "&gubun=2";
};

/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkMaxLength2
 * @description check Max Length2 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength2 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
